// keepPriorEmpty keeps the prior form of a value that is empty in both the
// prior data and the new state. The API does not tell null from an empty
// list, set, or map, or a missing object outside a oneOf from an empty one
// (contract 2.2, 2.9). So the state keeps the form that the configuration
// has, and Terraform sees no difference.
func keepPriorEmpty(ctx context.Context, prior tfData, state *tfsdk.State) diag.Diagnostics {
	var diags diag.Diagnostics
	attrs := state.Schema.GetAttributes()
	names := make([]string, 0, len(attrs))
	for name := range attrs {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		var p, v attr.Value
		diags.Append(prior.GetAttribute(ctx, path.Root(name), &p)...)
		diags.Append(state.GetAttribute(ctx, path.Root(name), &v)...)
		if diags.HasError() {
			return diags
		}
		if kept := priorEmpty(ctx, name, v, p, &diags); !kept.Equal(v) {
			diags.Append(state.SetAttribute(ctx, path.Root(name), kept)...)
		}
	}
	return diags
}

// priorEmpty returns p when v and p are both empty at path at. Otherwise it
// returns v, with the same rule applied to the attributes of an object and to
// the elements of a list or map.
func priorEmpty(ctx context.Context, at string, v, p attr.Value, diags *diag.Diagnostics) attr.Value {
	// A read can leave out a nested value that equals its declared server default.
	if d := defaultAttrs[at]; d != nil && v.IsNull() && p != nil && p.Equal(d) {
		return p
	}
	if keepAPIValue(at, v, p) {
		return v
	}
	if emptyValue(at, v) && emptyValue(at, p) {
		return p
	}
	if v.IsNull() || p.IsNull() {
		return v
	}
	switch v := v.(type) {
	case types.Object:
		if prior, ok := p.(types.Object); ok {
			return priorEmptyObject(ctx, at, v, prior, diags)
		}
	case types.List:
		if prior, ok := p.(types.List); ok {
			return priorEmptyList(ctx, at, v, prior, diags)
		}
	case types.Map:
		if prior, ok := p.(types.Map); ok {
			return priorEmptyMap(ctx, at, v, prior, diags)
		}
	}
	return v
}

// keepAPIValue reports whether v needs no rule: a value is missing or
// unknown, the values are equal, or the attribute is computed or required and
// the prior has no value, for example after an import. Terraform does not
// compare a computed attribute that the configuration leaves out, so the value
// of the API is safe. A required attribute has no null in state or in the
// configuration, so a null prior can only come from an import, and the empty
// value of the API (rules = []) is the one that the configuration sets. An
// empty value stays known.
func keepAPIValue(at string, v, p attr.Value) bool {
	if v == nil || p == nil || v.IsUnknown() || p.IsUnknown() || v.Equal(p) {
		return true
	}
	return p.IsNull() && (computedAttrs[at] || requiredAttrs[at])
}

func priorEmptyObject(ctx context.Context, at string, v, prior types.Object, diags *diag.Diagnostics) attr.Value {
	attrs, priorAttrs := v.Attributes(), prior.Attributes()
	out := make(map[string]attr.Value, len(attrs))
	for name, child := range attrs {
		out[name] = priorEmpty(ctx, at+"."+name, child, priorAttrs[name], diags)
	}
	value, d := types.ObjectValue(v.AttributeTypes(ctx), out)
	diags.Append(d...)
	return value
}

// priorEmptyList pairs elements by index, so it needs lists of one length.
func priorEmptyList(ctx context.Context, at string, v, prior types.List, diags *diag.Diagnostics) attr.Value {
	elems, priorElems := v.Elements(), prior.Elements()
	if len(elems) != len(priorElems) {
		return v
	}
	out := make([]attr.Value, len(elems))
	for i, child := range elems {
		out[i] = priorEmpty(ctx, at, child, priorElems[i], diags)
	}
	value, d := types.ListValue(v.ElementType(ctx), out)
	diags.Append(d...)
	return value
}

func priorEmptyMap(ctx context.Context, at string, v, prior types.Map, diags *diag.Diagnostics) attr.Value {
	elems, priorElems := v.Elements(), prior.Elements()
	out := make(map[string]attr.Value, len(elems))
	for key, child := range elems {
		out[key] = priorEmpty(ctx, at, child, priorElems[key], diags)
	}
	value, d := types.MapValue(v.ElementType(ctx), out)
	diags.Append(d...)
	return value
}

// emptyValue reports whether v is null, an empty list, set, or map, or an
// object outside a oneOf arm whose attributes are all empty.
func emptyValue(at string, v attr.Value) bool {
	if v.IsNull() {
		return true
	}
	if v.IsUnknown() {
		return false
	}
	switch v := v.(type) {
	case types.List:
		return len(v.Elements()) == 0
	case types.Set:
		return len(v.Elements()) == 0
	case types.Map:
		return len(v.Elements()) == 0
	case types.Object:
		if oneOfArms[at] {
			return false
		}
		for name, child := range v.Attributes() {
			if !emptyValue(at+"."+name, child) {
				return false
			}
		}
		return true
	}
	return false
}

// distributedActions holds the Actions list of one request or one response. The list is no
// attribute of the resource: each item of it is an attribute of the object that it names. Expand
// collects the items of every object, and flatten gives each object the items that name it.
type distributedActions struct {
	items []dashboard_service.DashboardAction
}

type distributedActionsKey struct{}

// withDistributedActions returns ctx with a new collector that holds items.
func withDistributedActions(ctx context.Context, items []dashboard_service.DashboardAction) (context.Context, *distributedActions) {
	d := &distributedActions{items: items}
	return context.WithValue(ctx, distributedActionsKey{}, d), d
}

// distributedActionsOf returns the collector of ctx, or nil when ctx has none.
func distributedActionsOf(ctx context.Context) *distributedActions {
	d, _ := ctx.Value(distributedActionsKey{}).(*distributedActions)
	return d
}

// distributedActionsShown reports whether a response shows the item: it has a value at definition.customAction.
// Flatten drops the other items, so expand refuses them, or the write would lose them on the read.
func distributedActionsShown(a dashboard_service.DashboardAction) bool {
	return a.Definition != nil && a.Definition.CustomAction != nil
}

// of returns the items that name the object with the id, in the order of the list.
func (d *distributedActions) of(id string) []dashboard_service.DashboardAction {
	var out []dashboard_service.DashboardAction
	for _, a := range d.items {
		if !distributedActionsShown(a) {
			continue
		}
		if got := a.WidgetId; got != nil && *got == id {
			out = append(out, a)
		}
	}
	return out
}

func expandDashboardCreate(ctx context.Context, p path.Path, m *DashboardModel, diags *diag.Diagnostics) *dashboard_service.Dashboard {
	if m == nil {
		return nil
	}
	out := &dashboard_service.Dashboard{}
	ctx, collectedActions := withDistributedActions(ctx, nil)
	expandDashboardCreateTimeFrame(ctx, p.AtName("time_frame"), m.TimeFrame, out, diags)
	if items := expandElements[AnnotationModel](ctx, p.AtName("annotations"), m.Annotations, diags); items != nil {
		out.Annotations = make([]dashboard_service.Annotation, 0, len(items))
		for i := range items {
			out.Annotations = append(out.Annotations, *expandAnnotation(ctx, p.AtName("annotations").AtListIndex(i), &items[i], diags))
		}
	}
	out.Description = expandString(m.Description)
	if v := m.AutoRefresh; !v.IsNull() && !v.IsUnknown() {
		var nested DashboardAutoRefreshModel
		diags.Append(v.As(ctx, &nested, basetypes.ObjectAsOptions{})...)
		expandDashboardCreateAutoRefresh(ctx, p.AtName("auto_refresh"), &nested, out, diags)
	}
	if items := expandElements[FiltersFilterModel](ctx, p.AtName("filters"), m.Filters, diags); items != nil {
		out.Filters = make([]dashboard_service.FiltersFilter, 0, len(items))
		for i := range items {
			out.Filters = append(out.Filters, *expandFiltersFilter(ctx, p.AtName("filters").AtListIndex(i), &items[i], diags))
		}
	}
	{
		var inner *string
		inner = expandString(m.FolderId)
		out.FolderId = wrapUUID(inner)
	}
	out.FolderPath = expandFolderPath(ctx, p.AtName("folder_path"), m.FolderPath, diags)
	out.Layout = valueOf(expandLayout(ctx, p.AtName("layout"), m.Layout, diags))
	out.Name = valueOf(expandString(m.Name))
	out.SlugName = expandString(m.SlugName)
	if items := expandElements[VariableModel](ctx, p.AtName("variables"), m.Variables, diags); items != nil {
		out.Variables = make([]dashboard_service.Variable, 0, len(items))
		for i := range items {
			out.Variables = append(out.Variables, *expandVariable(ctx, p.AtName("variables").AtListIndex(i), &items[i], diags))
		}
	}
	if items := expandElements[VariableV2Model](ctx, p.AtName("variables_v2"), m.VariablesV2, diags); items != nil {
		out.VariablesV2 = make([]dashboard_service.VariableV2, 0, len(items))
		for i := range items {
			out.VariablesV2 = append(out.VariablesV2, *expandVariableV2(ctx, p.AtName("variables_v2").AtListIndex(i), &items[i], diags))
		}
	}
	out.Actions = collectedActions.items
	return out
}

