// expandDashboardCreateAutoRefresh sets the arm that the type attribute names in out, the API object that holds the
// arms of the group.
func expandDashboardCreateAutoRefresh(ctx context.Context, p path.Path, m *DashboardAutoRefreshModel, out *dashboard_service.Dashboard, diags *diag.Diagnostics) {
	if m == nil {
		return
	}
	kind := m.Type.ValueString()
	switch kind {
	case "fifteen_minutes":
		out.FifteenMinutes = map[string]interface{}{}
	case "five_minutes":
		out.FiveMinutes = map[string]interface{}{}
	case "off":
		out.Off = map[string]interface{}{}
	case "one_minute":
		out.OneMinute = map[string]interface{}{}
	case "two_minutes":
		out.TwoMinutes = map[string]interface{}{}
	default:
		diags.AddAttributeError(p.AtName("type"), "Unknown type", fmt.Sprintf("The type %q is not one of fifteen_minutes, five_minutes, off, one_minute, two_minutes.", m.Type.ValueString()))
	}
}

