func expandMultiSelect(ctx context.Context, p path.Path, m *MultiSelectModel, diags *diag.Diagnostics) *dashboard_service.MultiSelect {
	if m == nil {
		return nil
	}
	out := &dashboard_service.MultiSelect{}
	out.SelectionOptions = &dashboard_service.VariableSelectionOptions{} // an inlined object: its fields are top-level attributes
	if v := m.Selection; !v.IsNull() && !v.IsUnknown() {
		// No values select the arm without fields. Some values are the list arm.
		fold := &dashboard_service.MultiSelectSelection{}
		if values := expandElements[string](ctx, p.AtName("selected_values"), v, diags); len(values) == 0 {
			fold.All = map[string]interface{}{}
		} else {
			fold.List = &dashboard_service.MultiSelectSelectionListSelection{Values: values}
		}
		out.Selection = fold
	}
	out.SelectionOptions.SelectionType = expandEnum[dashboard_service.SelectionType](m.SelectionType)
	out.Source = expandMultiSelectSource(ctx, p.AtName("source"), m.Source, diags)
	out.ValuesOrderDirection = expandEnum[dashboard_service.OrderDirection](m.ValuesOrderDirection)
	if out.SelectionOptions != nil && modelNull(m.SelectionType) {
		out.SelectionOptions = nil // an optional object that the configuration sets no attribute of is left out
	}
	return out
}

func flattenMultiSelect(ctx context.Context, p path.Path, v *dashboard_service.MultiSelect, diags *diag.Diagnostics) *MultiSelectModel {
	if v == nil {
		return nil
	}
	// The fields of an inlined object read as null when the API returns no object.
	copied := *v
	v = &copied
	if v.SelectionOptions == nil {
		v.SelectionOptions = &dashboard_service.VariableSelectionOptions{}
	}
	out := &MultiSelectModel{}
	out.Selection = types.ListNull(types.StringType)
	if fold := v.Selection; fold != nil {
		switch {
		case fold.List != nil:
			out.Selection = flattenStringsList(ctx, append([]string{}, fold.List.Values...), diags)
		case fold.All != nil:
			out.Selection = flattenStringsList(ctx, []string{}, diags)
		}
	}
	out.SelectionType = flattenEnum(v.SelectionOptions.SelectionType, "SELECTION_TYPE_UNSPECIFIED")
	out.Source = flattenMultiSelectSource(ctx, p.AtName("source"), v.Source, diags)
	out.ValuesOrderDirection = flattenEnum(v.ValuesOrderDirection, "ORDER_DIRECTION_UNSPECIFIED")
	return out
}

